const j = $json.body || $json;
const from = String(j.From || j.from || '');
const body = String(j.Body || j.body || '');
const sid = String(j.MessageSid || j.SmsMessageSid || j.SmsSid || j.sid || ('IN' + Date.now()));
const digits = from.replace(/\D/g, '');
const upper = body.trim().toUpperCase();
let kind = 'reply';
if (/^(STOP|STOPALL|UNSUBSCRIBE|CANCEL|END|QUIT)$/.test(upper)) kind = 'stop';
else if (/^(START|UNSTOP)$/.test(upper) || /^JOIN\b/.test(upper)) kind = 'start';
else if (upper === 'HELP') kind = 'help';
return { json: { from, body, sid, digits, kind, now: new Date().toISOString() } };

const meta = $('Parse inbound').item.json;
const truthy = (v) => {
  if (typeof v === 'boolean') return v;
  if (typeof v === 'number') return v !== 0;
  if (typeof v === 'string') {
    const s = v.trim().toUpperCase();
    return s === 'TRUE' || s === '1' || s === 'YES';
  }
  return false;
};
const rows = $input.all().map(({ json: r }) => ({
  id: String(r.id || ''),
  phoneDigits: String(r.phone || '').replace(/\D/g, ''),
  stage: String(r.stage || '').toLowerCase(),
  waSentAt: String(r.waSentAt || '').trim(),
  waOptIn: truthy(r.waOptIn),
  updatedAt: r.updatedAt || '',
}));
const openEligible = (r) =>
  (r.stage === 'sent' || r.stage === 'replied') &&
  (r.waSentAt !== '' || r.waOptIn);
const matches = rows.filter(
  (r) => r.phoneDigits && r.phoneDigits === meta.digits && openEligible(r)
);
let attachInvoiceId = null;
if (matches.length === 1 && meta.kind === 'reply') {
  attachInvoiceId = matches[0].id;
}
return [{ json: {
  ...meta,
  matchIds: matches.map((m) => m.id),
  matchCount: matches.length,
  suggestedInvoiceId: matches.length === 1 ? matches[0].id : '',
  attachInvoiceId,
} }];

const meta = $json;
const ids = meta.matchIds || [];
if (!ids.length) return [{ json: { ...meta, logStatus: 'pending', patched: 0 } }];
return ids.map((id) => ({ json: { ...meta, id, waOptIn: 'FALSE', waOptOut: 'TRUE', logStatus: 'pending', patched: ids.length } }));

